import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const c=JSON.parse('{"title":"脚本作用域与数据流深度研究","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/脚本作用域与数据流深度研究.md","filePath":"脚本系统/专题研究/脚本作用域与数据流深度研究.md","lastUpdated":1776864657000}'),h={name:"脚本系统/专题研究/脚本作用域与数据流深度研究.md"};function n(p,l,t,d,o,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="脚本作用域与数据流深度研究" tabindex="-1">脚本作用域与数据流深度研究 <a class="header-anchor" href="#脚本作用域与数据流深度研究" aria-label="Permalink to “脚本作用域与数据流深度研究”">​</a></h1><p>本文基于 <code>资料/基础写脚本界面截图/</code> 中的作用域相关截图，以及已整理的脚本专题文档，进一步把“局部 / 自身 / 当前地图 / 系统”整理成更适合长期研究与问答的结构。</p><h2 id="_1-为什么要单独研究作用域" tabindex="-1">1. 为什么要单独研究作用域 <a class="header-anchor" href="#_1-为什么要单独研究作用域" aria-label="Permalink to “1. 为什么要单独研究作用域”">​</a></h2><p>在创游世界中，很多看似“同名的变量读写”，实际上处于不同层级。</p><p>从已整理截图可确认，脚本里至少频繁出现以下作用域：</p><ul><li>局部变量</li><li>自身属性</li><li>当前地图属性</li><li>系统属性</li></ul><p>这意味着创游脚本不是单层变量模型，而是一个<strong>多层状态系统</strong>。</p><p>如果不先理解作用域，后面很多现象都会难以解释，例如：</p><ul><li>为什么某个值在一个物体里改了，别的地方没变化</li><li>为什么 UI 里改数据会变慢</li><li>为什么广播后建议让地图来统一处理</li><li>为什么自定义组件适合封装局部能力，而不是无脑操作系统级数据</li></ul><hr><h2 id="_2-四层作用域的直观理解" tabindex="-1">2. 四层作用域的直观理解 <a class="header-anchor" href="#_2-四层作用域的直观理解" aria-label="Permalink to “2. 四层作用域的直观理解”">​</a></h2><h3 id="_2-1-局部变量" tabindex="-1">2.1 局部变量 <a class="header-anchor" href="#_2-1-局部变量" aria-label="Permalink to “2.1 局部变量”">​</a></h3><p>局部变量更像：</p><ul><li>当前脚本执行过程中的临时值</li><li>某次触发中的中间结果</li><li>某个流程节点之间传递的数据</li></ul><p>特点：</p><ul><li>生命周期短</li><li>通常只在当前执行链中有效</li><li>更适合做计算缓存、条件判断中间值、一次性参数整理</li></ul><p>适合场景：</p><ul><li>暂存计算结果</li><li>拼接文本</li><li>临时记录目标对象或数值</li><li>避免重复读取同一个属性</li></ul><h3 id="_2-2-自身属性" tabindex="-1">2.2 自身属性 <a class="header-anchor" href="#_2-2-自身属性" aria-label="Permalink to “2.2 自身属性”">​</a></h3><p>自身属性更像：</p><ul><li>当前物体或当前组件自身持有的状态</li><li>某个对象实例的“私有数据”</li></ul><p>特点：</p><ul><li>与具体物体绑定</li><li>常用于记录该实例当前状态</li><li>很适合做对象行为控制</li></ul><p>适合场景：</p><ul><li>血量</li><li>冷却状态</li><li>开关状态</li><li>当前阶段</li><li>物体是否已激活</li></ul><h3 id="_2-3-当前地图属性" tabindex="-1">2.3 当前地图属性 <a class="header-anchor" href="#_2-3-当前地图属性" aria-label="Permalink to “2.3 当前地图属性”">​</a></h3><p>当前地图属性更像：</p><ul><li>当前场景级共享状态</li><li>地图内多个对象都可能需要读写的数据</li></ul><p>特点：</p><ul><li>作用域比单个物体更大</li><li>常用于关卡逻辑、全局流程、地图内共享计数</li><li>与“当前地图”这个运行上下文紧密相关</li></ul><p>适合场景：</p><ul><li>当前波次</li><li>地图计时</li><li>当前任务阶段</li><li>机关总开关</li><li>地图级广播驱动状态</li></ul><h3 id="_2-4-系统属性" tabindex="-1">2.4 系统属性 <a class="header-anchor" href="#_2-4-系统属性" aria-label="Permalink to “2.4 系统属性”">​</a></h3><p>系统属性更像：</p><ul><li>更全局、更基础、更跨地图的状态容器</li><li>高层共享状态</li></ul><p>特点：</p><ul><li>作用域最广</li><li>适合放全局级配置或运行状态</li><li>如果滥用，会让项目耦合严重</li></ul><p>适合场景：</p><ul><li>全局设置</li><li>跨地图状态</li><li>总难度配置</li><li>通用运行标记</li></ul><hr><h2 id="_3-创游脚本中的典型数据流" tabindex="-1">3. 创游脚本中的典型数据流 <a class="header-anchor" href="#_3-创游脚本中的典型数据流" aria-label="Permalink to “3. 创游脚本中的典型数据流”">​</a></h2><p>结合教程、脚本截图和联机 UI 更新说明，可以总结出几种典型数据流模式。</p><h3 id="模式-a-局部-自身" tabindex="-1">模式 A：局部 -&gt; 自身 <a class="header-anchor" href="#模式-a-局部-自身" aria-label="Permalink to “模式 A：局部 -&gt; 自身”">​</a></h3><p>最常见。</p><p>含义：</p><ul><li>先在流程里算出结果</li><li>再回写到当前物体状态</li></ul><p>适用：</p><ul><li>技能结算</li><li>行为判断</li><li>一次交互后的状态更新</li></ul><h3 id="模式-b-局部-当前地图" tabindex="-1">模式 B：局部 -&gt; 当前地图 <a class="header-anchor" href="#模式-b-局部-当前地图" aria-label="Permalink to “模式 B：局部 -&gt; 当前地图”">​</a></h3><p>含义：</p><ul><li>某个对象产生一个事件</li><li>把结果上报到地图级状态</li></ul><p>适用：</p><ul><li>收集品数量增加</li><li>某机关被触发</li><li>任务进度推进</li></ul><h3 id="模式-c-ui-对象-广播-当前地图" tabindex="-1">模式 C：UI/对象 -&gt; 广播 -&gt; 当前地图 <a class="header-anchor" href="#模式-c-ui-对象-广播-当前地图" aria-label="Permalink to “模式 C：UI/对象 -&gt; 广播 -&gt; 当前地图”">​</a></h3><p>这是较新的推荐模式。</p><p>含义：</p><ul><li>UI 或某物体不直接连续改公共数据</li><li>而是先发广播</li><li>再由地图脚本集中处理共享状态</li></ul><p>优势：</p><ul><li>降低同步压力</li><li>降低跨层耦合</li><li>更适合联机逻辑</li></ul><h3 id="模式-d-系统-地图-物体初始化" tabindex="-1">模式 D：系统 -&gt; 地图 / 物体初始化 <a class="header-anchor" href="#模式-d-系统-地图-物体初始化" aria-label="Permalink to “模式 D：系统 -&gt; 地图 / 物体初始化”">​</a></h3><p>含义：</p><ul><li>全局配置下发到当前场景或实例</li><li>运行开始后再由地图或物体各自管理自己的局部状态</li></ul><p>适用：</p><ul><li>难度初始化</li><li>全局规则读取</li><li>通用设置注入</li></ul><hr><h2 id="_4-为什么-广播-地图集中处理-很重要" tabindex="-1">4. 为什么“广播 + 地图集中处理”很重要 <a class="header-anchor" href="#_4-为什么-广播-地图集中处理-很重要" aria-label="Permalink to “4. 为什么“广播 + 地图集中处理”很重要”">​</a></h2><p>这个结论在引擎更新与教程内容中都有互证。</p><h3 id="旧思路的问题" tabindex="-1">旧思路的问题 <a class="header-anchor" href="#旧思路的问题" aria-label="Permalink to “旧思路的问题”">​</a></h3><p>很多人会习惯：</p><ul><li>在 UI 中直接连续改公共数据</li><li>在多个地方同时操作同一个全局状态</li><li>让对象跨层深度控制别的系统</li></ul><p>问题是：</p><ul><li>联机下会有同步成本</li><li>逻辑入口分散</li><li>排查困难</li><li>很容易产生“表面成功、实际错层”的问题</li></ul><h3 id="新思路" tabindex="-1">新思路 <a class="header-anchor" href="#新思路" aria-label="Permalink to “新思路”">​</a></h3><p>更推荐：</p><ul><li>输入层发意图</li><li>地图层做汇总</li><li>对象层做局部执行</li><li>UI 层做显示呈现</li></ul><p>也就是：</p><ul><li>UI 负责交互</li><li>广播负责通知</li><li>地图负责公共逻辑</li><li>物体负责自身状态</li></ul><p>这是一种明显更稳定的分层设计。</p><hr><h2 id="_5-作用域误用带来的典型问题" tabindex="-1">5. 作用域误用带来的典型问题 <a class="header-anchor" href="#_5-作用域误用带来的典型问题" aria-label="Permalink to “5. 作用域误用带来的典型问题”">​</a></h2><h3 id="_5-1-用系统属性存一切" tabindex="-1">5.1 用系统属性存一切 <a class="header-anchor" href="#_5-1-用系统属性存一切" aria-label="Permalink to “5.1 用系统属性存一切”">​</a></h3><p>后果：</p><ul><li>所有逻辑都耦合在一起</li><li>难以复用</li><li>难以排查来源</li><li>很难做地图级隔离</li></ul><h3 id="_5-2-用自身属性承载全局流程" tabindex="-1">5.2 用自身属性承载全局流程 <a class="header-anchor" href="#_5-2-用自身属性承载全局流程" aria-label="Permalink to “5.2 用自身属性承载全局流程”">​</a></h3><p>后果：</p><ul><li>多个对象状态不一致</li><li>流程推进分散</li><li>很难统一判断全局阶段</li></ul><h3 id="_5-3-用局部变量当持久状态" tabindex="-1">5.3 用局部变量当持久状态 <a class="header-anchor" href="#_5-3-用局部变量当持久状态" aria-label="Permalink to “5.3 用局部变量当持久状态”">​</a></h3><p>后果：</p><ul><li>下一次触发就丢失</li><li>表面上“刚算出来有值”，后续却找不到</li></ul><h3 id="_5-4-在-ui-里直接做大量公共数据写入" tabindex="-1">5.4 在 UI 里直接做大量公共数据写入 <a class="header-anchor" href="#_5-4-在-ui-里直接做大量公共数据写入" aria-label="Permalink to “5.4 在 UI 里直接做大量公共数据写入”">​</a></h3><p>后果：</p><ul><li>联机场景下更容易出现等待</li><li>性能和流畅度受影响</li><li>调试体验差</li></ul><hr><h2 id="_6-对项目架构的启发" tabindex="-1">6. 对项目架构的启发 <a class="header-anchor" href="#_6-对项目架构的启发" aria-label="Permalink to “6. 对项目架构的启发”">​</a></h2><h3 id="建议一-状态按层放置" tabindex="-1">建议一：状态按层放置 <a class="header-anchor" href="#建议一-状态按层放置" aria-label="Permalink to “建议一：状态按层放置”">​</a></h3><p>可以粗略按下面思路放：</p><ul><li>临时过程值：局部</li><li>实例状态：自身</li><li>场景状态：当前地图</li><li>跨场景配置：系统</li></ul><h3 id="建议二-优先从低耦合方向设计" tabindex="-1">建议二：优先从低耦合方向设计 <a class="header-anchor" href="#建议二-优先从低耦合方向设计" aria-label="Permalink to “建议二：优先从低耦合方向设计”">​</a></h3><p>推荐顺序：</p><ul><li>先想这个数据是不是只和当前物体有关</li><li>再想是不是地图共享</li><li>最后才考虑系统全局</li></ul><h3 id="建议三-让广播承担-传意图-职责" tabindex="-1">建议三：让广播承担“传意图”职责 <a class="header-anchor" href="#建议三-让广播承担-传意图-职责" aria-label="Permalink to “建议三：让广播承担“传意图”职责”">​</a></h3><p>广播更适合表达：</p><ul><li>发生了什么</li><li>想让谁处理什么</li></ul><p>而不是：</p><ul><li>广播后立刻塞入大量底层操作</li></ul><h3 id="建议四-让自定义组件封装-局部复杂性" tabindex="-1">建议四：让自定义组件封装“局部复杂性” <a class="header-anchor" href="#建议四-让自定义组件封装-局部复杂性" aria-label="Permalink to “建议四：让自定义组件封装“局部复杂性””">​</a></h3><p>自定义组件最适合：</p><ul><li>把某个物体自己的复杂行为关起来</li><li>对外只暴露必要指令</li></ul><p>而不是直接让每个物体到处读写系统级状态。</p><hr><h2 id="_7-可抽象出的创游数据分层模型" tabindex="-1">7. 可抽象出的创游数据分层模型 <a class="header-anchor" href="#_7-可抽象出的创游数据分层模型" aria-label="Permalink to “7. 可抽象出的创游数据分层模型”">​</a></h2><p>从当前证据看，可以暂时把创游的数据层理解为：</p><ol><li><strong>流程层</strong>：局部变量</li><li><strong>实例层</strong>：自身属性 / 自定义组件属性</li><li><strong>场景层</strong>：当前地图属性</li><li><strong>全局层</strong>：系统属性</li></ol><p>这四层不是孤立的，而是通过：</p><ul><li>指令</li><li>广播</li><li>事件触发</li><li>UI 通知</li><li>地图逻辑</li></ul><p>共同构成一个多层数据流系统。</p><hr><h2 id="_8-适合-ai-rag-的关键词" tabindex="-1">8. 适合 AI/RAG 的关键词 <a class="header-anchor" href="#_8-适合-ai-rag-的关键词" aria-label="Permalink to “8. 适合 AI/RAG 的关键词”">​</a></h2><ul><li>脚本作用域</li><li>局部变量</li><li>自身属性</li><li>当前地图属性</li><li>系统属性</li><li>数据流</li><li>广播</li><li>地图集中处理</li><li>联机同步</li><li>UI 分层</li><li>自定义组件</li><li>状态管理</li></ul><hr><h2 id="_9-后续还能继续深挖的问题" tabindex="-1">9. 后续还能继续深挖的问题 <a class="header-anchor" href="#_9-后续还能继续深挖的问题" aria-label="Permalink to “9. 后续还能继续深挖的问题”">​</a></h2><ol><li>局部变量在自定义指令嵌套调用中的可见范围</li><li>地图属性与系统属性在联机下的同步差异</li><li>UI 内部属性与地图公共属性之间的边界</li><li>玩家变量是否应独立建模为“第五层”</li><li>自定义组件属性与物体原生属性的优先级关系</li></ol>',122)])])}const _=i(h,[["render",n]]);export{c as __pageData,_ as default};
